<script setup lang="ts">
import {ref,watch,nextTick} from 'vue';import type {useEditorSafety} from './editor-safety';import {editorField} from '../../shared/editor-changes';
const props=defineProps<{state:ReturnType<typeof useEditorSafety>}>(),showInput=ref(false),panel=ref<HTMLElement>();
let previous:HTMLElement|null=null;watch(()=>props.state.leaveOpen.value,async open=>{if(open){previous=document.activeElement as HTMLElement;await nextTick();panel.value?.querySelector<HTMLElement>('button[autofocus]')?.focus();}else if(previous?.isConnected)previous.focus({preventScroll:true});});
const value=(v:unknown)=>v===undefined?'未设置':typeof v==='string'?v:JSON.stringify(v,null,2);
function trap(e:KeyboardEvent){if(e.key!=='Tab')return;const items=Array.from(panel.value?.querySelectorAll<HTMLElement>('button:not(:disabled)')||[]),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
</script>
<template><p v-if="state.dirty.value" class="editor-dirty" role="status">有尚未保存的修改</p><section v-if="state.error.value" class="editor-feedback" role="alert"><p>{{state.error.value}}</p><button v-if="state.conflict.value" :disabled="state.working.value" @click="state.compare">获取最新版本并比较差异</button><button v-if="state.conflict.value" @click="showInput=!showInput">查看当前未保存内容</button><pre v-if="showInput">{{value(state.current())}}</pre><section v-if="state.latest.value" class="conflict-review"><h2>版本差异（尚未保存）</h2><p>勾选要重新应用的当前修改。同一字段两边都变更时，默认保留最新版本；照片、阶段或关系列表作为整体比较。</p><article v-for="row in state.rows.value" :key="row.path.join('.')"><h3>{{editorField(row.path)}} {{row.contested?'· 两边均已修改':row.latestChanged?'· 其他窗口已更新':'· 当前修改'}}</h3><div class="comparison-values"><div><b>打开时</b><pre>{{value(row.base)}}</pre></div><div><b>当前输入</b><pre>{{value(row.mine)}}</pre></div><div><b>最新版本</b><pre>{{value(row.latest)}}</pre></div></div><label v-if="row.mineChanged"><input v-model="row.selected" type="checkbox">重新应用我的此项修改</label></article><label><input v-model="state.reviewed.value" type="checkbox">我已查看差异并确认以上选择</label><button :disabled="!state.reviewed.value||state.working.value||state.blocked.value" @click="state.reapply">按选择重新应用，继续编辑</button></section></section><Teleport to="body"><div v-if="state.leaveOpen.value" class="editor-leave-overlay" @keydown.stop="trap"><section ref="panel" role="dialog" aria-modal="true" aria-label="未保存修改"><h2>你有尚未保存的修改。</h2><p>保存失败会留在当前页并保留输入。</p><div class="field-actions"><button class="primary-action" :disabled="state.working.value" @click="state.saveAndLeave">保存并离开</button><button :disabled="state.working.value" @click="state.decide(true)">放弃修改</button><button autofocus :disabled="state.working.value" @click="state.decide(false)">继续编辑</button></div><p v-if="state.error.value" role="alert">{{state.error.value}}</p></section></div></Teleport></template>
